import{_ as i,a0 as n,w as p,s,I as o,x as e,a1 as t,A as d,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Fedora 26 助力雲、服務器、工作站系統 | LCTT x X-CMD","titleTemplate":false,"description":"Fedora 26 助力雲、服務器、工作站系統 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora 26 助力雲、服務器、工作站系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora 26 助力雲、服務器、工作站系統 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170715 Fedora 26 Powers Up Cloud Server Workstation Systems","title":"Fedora 26 助力雲、服務器、工作站系統","tag":"201708","desc":""},"relativePath":"201708/20170715 Fedora 26 Powers Up Cloud Server Workstation Systems.md","filePath":"[post].md"}'),u={name:"201708/20170715 Fedora 26 Powers Up Cloud Server Workstation Systems.md"};function F(m,r,f,T,b,x){const a=n("Link");return p(),s("div",null,[r[26]||(r[26]=o("h1",{id:"fedora-26-助力雲、服務器、工作站系統",tabindex:"-1"},[e("Fedora 26 助力雲、服務器、工作站系統 "),o("a",{class:"header-anchor",href:"#fedora-26-助力雲、服務器、工作站系統","aria-label":"Permalink to “Fedora 26 助力雲、服務器、工作站系統”"},"​")],-1)),o("p",null,[t(a,{href:"https://getfedora.org/"},{default:d(()=>[...r[0]||(r[0]=[e("Fedora 項目",-1)])]),_:1}),r[1]||(r[1]=e(" 7 月份宣佈推出 Fedora 26, 它是全面開放源代碼的 Fedora 操作系統的最新版本。",-1))]),r[27]||(r[27]=l('<p><img src="http://www.linuxinsider.com/ai/631127/fedora.jpg" alt="Fedora 26 Powers Up Cloud, Server, Workstation Systems"></p><p>Fedora Linux 是 Red Hat Enterprise Linux（RHEL）的社區版本。Fedora 26 包含一組基礎包，形成針對不同用户的三個不同版本的基礎。</p><p>Fedora <ruby>原子主機版<rt>Atomic Host Edition</rt></ruby> 是用於運行基於容器的工作的操作系統。Fedora <ruby>服務器版<rt>Server</rt></ruby>將 Fedora Server OS 安裝在硬盤驅動器上。Fedora <ruby>工作站版<rt>Workstation</rt></ruby>是一款用於筆記本電腦和台式機的用户友好操作系統，它適用於廣泛的用户 - 從業餘愛好者和學生到企業環境中的專業人士。</p><p>所有這三個版本都有共同的基礎和一些共同的優點。所有 Fedora 版本每年發行兩次。</p><p>Fedora 項目是創新和新功能的測試基地。Fedora 項目負責人 Matthew Miller 説，有些特性將在即將發佈的 RHEL 版本中實現。</p><p>他告訴 LinuxInsider：“Fedora 並沒有直接參與這些產品化決策。Fedora 提供了許多想法和技術，它是 Red Hat Enterprise Linux 客户參與並提供反饋的好地方。”</p><h3 id="強力的軟件包" tabindex="-1">強力的軟件包 <a class="header-anchor" href="#強力的軟件包" aria-label="Permalink to “強力的軟件包”">​</a></h3><p>Fedora 開發人員更新和改進了所有三個版本的軟件包。他們在 Fedora 26 中進行了許多錯誤修復和性能調整，以便在 Fedora 的用例中提供更好的用户體驗。</p><p>這些安裝包包括以下改進：</p><ul><li>更新的編譯器和語言，包括 GCC 7、Go 1.8、Python 3.6 和 Ruby 2.4；</li><li>DNF 2.0 是 Fedora 下一代包管理系統的最新版本，它與 Yum 的向後兼容性得到改善；</li><li>Anaconda 安裝程序新的存儲配置界面，可從設備和分區進行自下而上的配置；</li><li>Fedora Media Writer 更新，使用户可以為基於 ARM 的設備（如 Raspberry Pi）創建可啓動 SD 卡。</li></ul>',10)),o("p",null,[t(a,{href:"http://www.ndpta.com/"},{default:d(()=>[...r[2]||(r[2]=[e("Endpoint Technologies Associates",-1)])]),_:1}),r[3]||(r[3]=e(" 的總裁 Roger L. Kay 指出，雲工具對於使用雲的用户必不可少，尤其是程序員。",-1))]),r[28]||(r[28]=o("p",null,"他對 LinuxInsider 表示：“Kubernetes 對於在混合雲中編程感興趣的程序員來説是至關重要的，這可能是目前業界更重要的發展之一。雲，無論是公有云、私有云還是混合雲 - 都是企業計算未來的關鍵。”",-1)),r[29]||(r[29]=o("h3",{id:"fedora-26-原子主機亮相",tabindex:"-1"},[e("Fedora 26 原子主機亮相 "),o("a",{class:"header-anchor",href:"#fedora-26-原子主機亮相","aria-label":"Permalink to “Fedora 26 原子主機亮相”"},"​")],-1)),r[30]||(r[30]=o("p",null,"Linux 容器和容器編排引擎一直在普及。Fedora 26 原子主機提供了一個最小佔用的操作系統，專門用於在裸機到雲端的環境中運行基於容器的工作任務。",-1)),r[31]||(r[31]=o("p",null,"Fedora 26 原子主機更新大概每兩週發佈一次，這個時間表可以讓用户及時跟上游創新。",-1)),o("p",null,[r[5]||(r[5]=e("Fedora 26 原子主機可用於 Amazon EC2 。OpenStack、Vagrant 鏡像和標準安裝程序 ISO 鏡像可在 ",-1)),t(a,{href:"https://getfedora.org/"},{default:d(()=>[...r[4]||(r[4]=[e("Fedora 項目",-1)])]),_:1}),r[6]||(r[6]=e("網站上找到。",-1))]),r[32]||(r[32]=l('<p>最小化的 Fedora 原子的容器鏡像也在 Fedora 26 上首次亮相。</p><h3 id="雲託管" tabindex="-1">雲託管 <a class="header-anchor" href="#雲託管" aria-label="Permalink to “雲託管”">​</a></h3><p>最新版本為 Fedora 26 原子主機提供了新功能和特性：</p><ul><li>容器化的 Kubernetes 作為內置的 Kubernetes 二進制文件的替代品，使用户更容易地運行不同版本的容器編排引擎；</li><li>最新版本的 rpm-ostree，其中包括支持直接 RPM 安裝，重新加載命令和清理命令;</li><li>系統容器，它提供了一種在容器中的 Fedora 原子主機上安裝系統基礎設施軟件（如網絡或 Kubernetes）的方法；</li><li>更新版本的 Docker、Atomic和 Cockpit，用於增強容器構建，系統支持和負載監控。</li></ul><p>根據 Fedora 項目的 Miller 所言，容器化的 Kubernetes 對於 Fedora 原子主機來説是重要的，有兩個重要原因。</p><p>他解釋説：“首先，它可以讓我們從基礎鏡像中刪除它，減小大小和複雜度。第二，在容器中提供它可以輕鬆地在不同版本中切換，而不會破環基礎，或者為尚未準備好進行改變的人造成麻煩。”</p><h3 id="服務器端服務" tabindex="-1">服務器端服務 <a class="header-anchor" href="#服務器端服務" aria-label="Permalink to “服務器端服務”">​</a></h3><p>Fedora 26 服務器版為數據中心運營提供了一個靈活的多角色平台。它還允許用户自定義此版本的 Fedora 操作系統以滿足其獨特需求。</p><p>Fedora 26 服務器版的新功能包括 FreeIPA 4.5，它可以改進容器中運行的安全信息管理解決方案，以及 SSSD 文件緩存，以加快用户和組查詢的速度。</p><p>Fedora 26 服務器版月底將增加稱為 “Boltron” 的 Fedora 模組化技術預覽。作為模組化操作系統，Boltron 使不同版本的不同應用程序能夠在同一個系統上運行，這實質上允許將前沿運行時與穩定的資料庫配合使用。</p><h3 id="打磨工作站版" tabindex="-1">打磨工作站版 <a class="header-anchor" href="#打磨工作站版" aria-label="Permalink to “打磨工作站版”">​</a></h3><p>對於一般用户的新工具和功能之一是更新的 GNOME 桌面功能。開發將獲得增強的生產力工具。</p>',12)),o("p",null,[r[8]||(r[8]=e("Fedora 26 工作站版附帶 GNOME 3.24 和眾多更新的功能調整。夜光根據時間細微地改變屏幕顏色，以減少對睡眠模式的影響。",-1)),t(a,{href:"http://www.libreoffice.org/"},{default:d(()=>[...r[7]||(r[7]=[e("LibreOffice",-1)])]),_:1}),r[9]||(r[9]=e(" 5.3 是開源辦公生產力套件的最新更新。",-1))]),r[33]||(r[33]=o("p",null,"GNOME 3.24 提供了 Builder 和 Flatpak 的成熟版本，它為開發人員提供了更好的應用程序開發工具，它可以方便地訪問各種系統，包括 Rust 和 Meson。",-1)),r[34]||(r[34]=o("h3",{id:"不只是為了開發",tabindex:"-1"},[e("不只是為了開發 "),o("a",{class:"header-anchor",href:"#不只是為了開發","aria-label":"Permalink to “不只是為了開發”"},"​")],-1)),o("p",null,[r[11]||(r[11]=e("根據 ",-1)),t(a,{href:"https://www.azul.com/"},{default:d(()=>[...r[10]||(r[10]=[e("Azul Systems",-1)])]),_:1}),r[12]||(r[12]=e(" 的首席執行官 Scott Sellers 的説法，更新的雲工具將納入針對企業用户的 Linux 發行版中。",-1))]),r[35]||(r[35]=l('<p>他告訴 LinuxInsider：“雲是新興公司以及地球上一些最大的企業的主要開發和生產平台。”</p><p>Sellers説：“鑑於 Fedora 社區的前沿性質，我們預計在任何 Fedora 版本中都會強烈關注雲技術，Fedora 26 不會不令人失望。”</p><p>他指出，Fedora 開發人員和用户社區的另一個特點就是 Fedora 團隊在模組化方面所做的工作。</p><p>Sellers 説：“我們將密切關注這些實驗功能。”</p><h3 id="支持的升級方式" tabindex="-1">支持的升級方式 <a class="header-anchor" href="#支持的升級方式" aria-label="Permalink to “支持的升級方式”">​</a></h3><p>Sellers 説 Fedora 的用户超過其他 Linux 發行版的用户，很多都有興趣升級到 Fedora 26，即使他們不是重度雲端用户。</p><p>他説：“這個發行版的主要優點之一就是能提前看到先進的生產級別技術，這些最終將被整合到 RHEL 中。Fedora 26 的早期評論表明它非常穩定，修復了許多錯誤以及提升了性能。”</p><p>Fedora 的 Miller 指出，有興趣從早期 Fedora 版本升級的用户可能比擦除現有系統安裝 Fedora 26 更容易。Fedora 一次維護兩個版本，中間還有一個月的重疊。</p><p>他説：“所以，如果你在用 Fedora 24，你應該在下個月升級。幸運的 Fedora 25 用户可以隨時升級，這是 Fedora 快速滾動版本的優勢之一。”</p><h3 id="更快的發佈" tabindex="-1">更快的發佈 <a class="header-anchor" href="#更快的發佈" aria-label="Permalink to “更快的發佈”">​</a></h3><p>用户可以安排自己升級，而不是在發行版製作出來時進行升級。</p><p>也就是説，Fedora 23 或更早版本的用户應該儘快升級。社區不再為這些版本發佈安全更新</p><hr><p>作者簡介：</p><p>Jack M. Germain 自 2003 年以來一直是 ECT 新聞網記者。他的主要重點領域是企業IT、Linux、和開源技術。他撰寫了許多關於 Linux 發行版和其他開源軟件的評論。發郵件聯繫 Jack</p><hr>',16)),o("p",null,[r[14]||(r[14]=e("via: ",-1)),t(a,{href:"http://www.linuxinsider.com/story/84674.html"},{default:d(()=>[...r[13]||(r[13]=[e("http://www.linuxinsider.com/story/84674.html",-1)])]),_:1})]),o("p",null,[r[18]||(r[18]=e("作者：",-1)),t(a,{href:"jack.germain@newsroom.ectnews.comm"},{default:d(()=>[...r[15]||(r[15]=[e("Jack M. Germain",-1)])]),_:1}),r[19]||(r[19]=e(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:d(()=>[...r[16]||(r[16]=[e("geekpi",-1)])]),_:1}),r[20]||(r[20]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:d(()=>[...r[17]||(r[17]=[e("wxy",-1)])]),_:1})]),o("p",null,[r[23]||(r[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...r[21]||(r[21]=[e("LCTT",-1)])]),_:1}),r[24]||(r[24]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:d(()=>[...r[22]||(r[22]=[e("Linux中國",-1)])]),_:1}),r[25]||(r[25]=e(" 榮譽推出",-1))])])}const k=i(u,[["render",F]]);export{C as __pageData,k as default};
